-- Auto-generated seed for one login per role.
-- Password for each user is <role>123 (e.g. hr/hr123). bcrypt-hashed at generation time.
BEGIN;
SELECT u.username, string_agg(r.name, ',') AS roles FROM users u LEFT JOIN user_roles ur ON u.id=ur.user_id LEFT JOIN roles r ON ur.role_id=r.id GROUP BY u.username ORDER BY u.username;
COMMIT;